PRIMITIVE_ROOT = 3


def ntt(a, invert):
    n = len(a)

    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        half = length >> 1
        if invert:
            wlen = pow(PRIMITIVE_ROOT, (MOD - 1) - (MOD - 1) // length, MOD)
        else:
            wlen = pow(PRIMITIVE_ROOT, (MOD - 1) // length, MOD)

        roots = [1] * half
        for i in range(1, half):
            roots[i] = roots[i - 1] * wlen % MOD

        for start in range(0, n, length):
            end = start + half
            for j in range(half):
                u = a[start + j]
                v = a[end + j] * roots[j] % MOD
                a[start + j] = u + v if u + v < MOD else u + v - MOD
                a[end + j] = u - v if u >= v else u - v + MOD

        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


